-- Execute uma vez no SQL Editor do Supabase
-- GT3 Sistema — Cadastro Contratantes: fichas de contratantes e favoritos por usuário

CREATE TABLE IF NOT EXISTS public.contratantes (
  id          TEXT        PRIMARY KEY,
  name        TEXT        NOT NULL,
  sheet_name  TEXT        NOT NULL DEFAULT '',
  segment     TEXT        NOT NULL DEFAULT '',
  updated     TEXT        NOT NULL DEFAULT '',
  fields      JSONB       NOT NULL DEFAULT '[]',
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_contratantes_segment ON public.contratantes(segment);

CREATE TABLE IF NOT EXISTS public.contratantes_favs (
  user_id     UUID        NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  company_id  TEXT        NOT NULL REFERENCES public.contratantes(id) ON DELETE CASCADE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, company_id)
);

-- Trigger updated_at
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS contratantes_updated_at ON public.contratantes;
CREATE TRIGGER contratantes_updated_at
  BEFORE UPDATE ON public.contratantes
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- ── RLS ──────────────────────────────────────────────────────────────────────

ALTER TABLE public.contratantes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.contratantes_favs ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "ct_select"        ON public.contratantes;
DROP POLICY IF EXISTS "ct_insert_gestor" ON public.contratantes;
DROP POLICY IF EXISTS "ct_update_gestor" ON public.contratantes;
DROP POLICY IF EXISTS "ct_delete_gestor" ON public.contratantes;

CREATE POLICY "ct_select"
  ON public.contratantes FOR SELECT TO authenticated
  USING (true);

CREATE POLICY "ct_insert_gestor"
  ON public.contratantes FOR INSERT TO authenticated
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND papel IN ('gestor', 'admin')
    )
  );

CREATE POLICY "ct_update_gestor"
  ON public.contratantes FOR UPDATE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND papel IN ('gestor', 'admin')
    )
  );

CREATE POLICY "ct_delete_gestor"
  ON public.contratantes FOR DELETE TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.profiles
      WHERE id = auth.uid() AND papel IN ('gestor', 'admin')
    )
  );

-- Favorites: each user manages their own rows
DROP POLICY IF EXISTS "fav_select" ON public.contratantes_favs;
DROP POLICY IF EXISTS "fav_insert" ON public.contratantes_favs;
DROP POLICY IF EXISTS "fav_delete" ON public.contratantes_favs;

CREATE POLICY "fav_select"
  ON public.contratantes_favs FOR SELECT TO authenticated
  USING (user_id = auth.uid());

CREATE POLICY "fav_insert"
  ON public.contratantes_favs FOR INSERT TO authenticated
  WITH CHECK (user_id = auth.uid());

CREATE POLICY "fav_delete"
  ON public.contratantes_favs FOR DELETE TO authenticated
  USING (user_id = auth.uid());

-- ── Realtime ─────────────────────────────────────────────────────────────────

ALTER TABLE public.contratantes REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.contratantes;

